mapper.insert:
insert into agent_skill_hub_builtin_state(source_key, source_commit_hash, indexed_at)
select #{sourceKey}, null, #{indexedAt}
where not exists (select 1 from agent_skill_hub_builtin_state where source_key = #{sourceKey})

mapper.update:
update agent_skill_hub_builtin_state
set source_commit_hash = #{sourceCommitHash}, indexed_at = #{indexedAt}
where source_key = #{sourceKey}

mapper.insert:
insert into agent_skill_hub_builtin_classifications(
    asset_id, skill_category, skill_subcategory, classified_by_user_id, classified_at)
select #{assetId}, #{skillCategory}, null, null, #{classifiedAt}
where not exists (
    select 1 from agent_skill_hub_builtin_classifications where asset_id = #{assetId}
)

mapper.update:
update agent_skill_hub_builtin_classifications
set skill_category = #{skillCategory}, skill_subcategory = #{skillSubcategory},
    classified_by_user_id = #{classifiedByUserId}, classified_at = #{classifiedAt}
where asset_id = #{assetId}
  and exists (
      select 1 from agent_skill_hub_builtin_revisions revision
      where revision.asset_id = #{assetId} and revision.asset_type = 'SKILL'
  )

update agent_skill_hub_assets set latest_pushed_revision_id = #{revisionId}, updated_at = #{pushedAt}
where asset_id = #{assetId} and (latest_pushed_revision_id is null or
  (select pushed_at from agent_skill_hub_revisions where revision_id = latest_pushed_revision_id) <= #{pushedAt})

mapper.select:
select a.asset_id as assetId, a.source_app_id as sourceAppId, a.source_application_workspace_id as sourceApplicationWorkspaceId, a.asset_type as assetType, a.technical_id as technicalId, a.skill_category as skillCategory, a.skill_subcategory as skillSubcategory, a.latest_pushed_revision_id as latestPushedRevisionId, a.latest_published_revision_id as latestPublishedRevisionId, a.created_at as assetCreatedAt, a.updated_at as assetUpdatedAt, pr.revision_id as pushedRevisionId, pr.source_version_id as pushedSourceVersionId, pr.source_commit_hash as pushedSourceCommitHash, pr.artifact_sha256 as pushedArtifactSha256, pr.content_sha256 as pushedContentSha256, pr.display_name as pushedDisplayName, pr.display_name_en as pushedDisplayNameEn, pr.description as pushedDescription, pr.deleted as pushedDeleted, pr.pushed_at as pushedAt, pr.published_at as pushedPublishedAt, pr.published_by_user_id as pushedPublishedByUserId, pub.revision_id as publishedRevisionId, pub.source_version_id as publishedSourceVersionId, pub.source_commit_hash as publishedSourceCommitHash, pub.artifact_sha256 as publishedArtifactSha256, pub.content_sha256 as publishedContentSha256, pub.display_name as publishedDisplayName, pub.display_name_en as publishedDisplayNameEn, pub.description as publishedDescription, pub.deleted as publishedDeleted, pub.pushed_at as publishedPushedAt, pub.published_at as publishedAt, pub.published_by_user_id as publishedByUserId, app.app_name as sourceAppName, aw.workspace_name as sourceWorkspaceName, (a.latest_published_revision_id is not null and pr.content_sha256 <> pub.content_sha256) as updateAvailable, (select ref.status from agent_skill_hub_references ref join application_members mem on mem.app_id = ref.target_app_id where ref.asset_id = a.asset_id and mem.user_id = #{currentUserId} and mem.deleted_at is null
and ref.target_application_workspace_id = #{targetWorkspaceId}
order by case ref.status when 'PENDING_REMOVE' then 1 when 'UPDATE_CONFLICT' then 2 when 'ACTIVE' then 3 when 'PENDING_PUSH' then 4 else 5 end, ref.updated_at desc limit 1) as referenceStatus, (select count(distinct effective_ref.target_app_id) from agent_skill_hub_references effective_ref where effective_ref.asset_id = a.asset_id and effective_ref.status in ('ACTIVE', 'UPDATE_CONFLICT')) as referenceCount from agent_skill_hub_assets a join agent_skill_hub_revisions pr on pr.revision_id = a.latest_pushed_revision_id left join agent_skill_hub_revisions pub on pub.revision_id = a.latest_published_revision_id join applications app on app.app_id = a.source_app_id join application_workspaces aw on aw.workspace_id = a.source_application_workspace_id
order by coalesce(pub.published_at, pr.pushed_at) desc, a.asset_id limit #{limit} offset #{offset}

select * from agent_skill_hub_references
where target_application_workspace_id = #{targetWorkspaceId} and asset_id = #{assetId}
order by updated_at desc, reference_id

mapper.update:
update agent_skill_hub_references set target_path = #{targetPath}, alias_technical_id = #{aliasTechnicalId},
  active_revision_id = #{activeRevisionId}, pending_revision_id = #{pendingRevisionId},
  pending_content_sha256 = #{pendingContentSha256}, status = #{status}, updated_at = #{updatedAt}
where reference_id = #{referenceId}

mapper.sql:
where mem.user_id = #{userId} and mem.deleted_at is null and a.latest_published_revision_id is not null and r.status <> 'PENDING_REMOVE'
and r.target_application_workspace_id = #{targetWorkspaceId}
and (r.status = 'PENDING_PUSH' or r.active_revision_id is null or (select active_revision.content_sha256 from agent_skill_hub_revisions active_revision where active_revision.revision_id = r.active_revision_id) <> (select latest_revision.content_sha256 from agent_skill_hub_revisions latest_revision where latest_revision.revision_id = a.latest_published_revision_id))
